begin; set local request.jwt.claims='{"role":"service_role"}';
do $test$
declare r uuid:=gen_random_uuid(); a uuid; b uuid; d uuid; st jsonb; snap jsonb;
begin
 insert into rooms(id,room_code,league)values(r,upper(substr(md5(random()::text),1,6)),'nfl');
 insert into players(room_id,player_name,is_cpu)values(r,'Automatic test A',false)returning id into a;
 insert into players(room_id,player_name,is_cpu)values(r,'Automatic test B',false)returning id into b;
 snap='{"available":true,"revision":1,"state":"in","current":{"source_id":"one","number":1,"quarter":1,"plays":0,"terminal":false},"completed":[]}'::jsonb;
 perform drive_duel_apply_feed(r,'test-auto',snap,0,0);
 select active_drive_id into d from room_game_state where room_id=r;
 insert into predictions(drive_id,player_id,predicted_outcome,is_locked,prediction_type)values(d,a,'Punt',true,'offense'),(d,a,'Force a punt',true,'defense');
 snap='{"available":true,"revision":2,"state":"in","current":{"source_id":"two","number":2,"quarter":1,"plays":0,"terminal":false},"completed":[{"source_id":"one","confirmed":true,"outcome":"Punt","conversion_success":null}]}'::jsonb;
 perform drive_duel_apply_feed(r,'test-auto',snap,0,0);
 if (select score from players where id=a)<>0 then raise exception 'Scored before confirmation';end if;
 update drives set pending_since=clock_timestamp()-interval '3 seconds' where id=d;
 perform drive_duel_apply_feed(r,'test-auto',snap,0,0);
 perform drive_duel_apply_feed(r,'test-auto',snap,0,0);
 if (select score from players where id=a)<>20 then raise exception 'Punt offense/defense exactly-once scoring failed';end if;
 if (select score from players where id=b)<>0 then raise exception 'Skipped player scored';end if;
 select active_drive_id into d from room_game_state where room_id=r;
 if (select feed_drive_id from drives where id=d)<>'two' then raise exception 'Shared advance failed';end if;
 insert into predictions(drive_id,player_id,predicted_outcome,is_locked,prediction_type)values(d,a,'Touchdown',true,'offense'),(d,b,'Touchdown',true,'offense');
 snap='{"available":true,"revision":3,"state":"in","current":{"source_id":"two","number":2,"quarter":1,"plays":3,"terminal":true},"completed":[]}'::jsonb;
 perform drive_duel_apply_feed(r,'test-auto',snap,6,0);
 if (select score from players where id=a)<>20 or not(select feed_closed from drives where id=d) then raise exception 'TD conversion pending failed';end if;
 snap='{"available":true,"revision":4,"state":"in","current":{"source_id":"three","number":3,"quarter":2,"plays":0,"terminal":false},"completed":[{"source_id":"two","confirmed":true,"outcome":"Touchdown","conversion_success":true}]}'::jsonb;
 perform drive_duel_apply_feed(r,'test-auto',snap,7,0);
 update drives set pending_since=clock_timestamp()-interval '3 seconds' where id=d;
 perform drive_duel_apply_feed(r,'test-auto',snap,7,0);
 perform drive_duel_apply_feed(r,'test-auto',snap,7,0);
 if (select score from players where id=a)<>32 or(select score from players where id=b)<>12 then raise exception 'TD +2 bonus or duplicate score failed';end if;
 select active_drive_id into d from room_game_state where room_id=r;
 insert into predictions(drive_id,player_id,predicted_outcome,is_locked,prediction_type)values(d,a,'Touchdown',true,'offense');
 snap='{"available":true,"revision":5,"state":"post","current":null,"completed":[{"source_id":"three","confirmed":true,"outcome":"Touchdown","conversion_success":false}]}'::jsonb;
 perform drive_duel_apply_feed(r,'test-auto',snap,13,0);
 update drives set pending_since=clock_timestamp()-interval '3 seconds' where id=d;
 perform drive_duel_apply_feed(r,'test-auto',snap,13,0);
 if (select score from players where id=a)<>42 then raise exception 'Missed conversion wrongly removed TD or added bonus';end if;
 if (select active_drive_id from room_game_state where room_id=r)is not null then raise exception 'Final game opened phantom drive';end if;
 perform drive_duel_apply_feed(r,'test-auto','{"available":true,"revision":1,"state":"in","current":{"source_id":"one","number":1,"quarter":1,"plays":0},"completed":[]}',0,0);
 if (select revision from room_game_state where room_id=r)<>5 then raise exception 'Stale feed regressed state';end if;
 if has_function_privilege('authenticated','public.drive_duel_apply_feed(uuid,text,jsonb,integer,integer)','execute') then raise exception 'Clients can forge feed results';end if;
 if has_function_privilege('authenticated','public.drive_duel_score_drive(uuid,text,boolean)','execute') then raise exception 'Clients can manually award points';end if;
 if has_table_privilege('authenticated','public.players','update') then raise exception 'Clients can overwrite scores';end if;
end $test$; rollback;
select 'PASS: atomic offense/defense scoring, skipped picks, next drive, TD conversion hold/success/miss, duplicate protection, final game, stale feed and service-only scoring' as validation;